/* mindist.c -- exact minimum distance of the self-dual code generated by [I_n | A].
   Usage: mindist n d < bits    (bits: n*n characters 0/1, row-major A)
   A word of weight < d has weight <= (d-1)/2 on its left half or on its right half.
   Left half = which rows of G = [I|A] it combines; right half = which rows of
   G' = [A^T|I] (same code, since it is self-dual). So enumerating every combination of
   <= t = (d-1)/2 rows of G and of G' finds every word below d. Prints the smallest
   weight seen (exact if < d), "d>=D" if none, and the row sets (left halves) of up to
   500 words below d, as lines "light i j k ...". n <= 64 (words fit in 2 x uint64). */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
static int n, d, t, minw = 1 << 30, nlight = 0;
static uint64_t L[2][64], Rt[2][64];   /* [side][row]: left / right halves */
static void dfs(int side, int start, int depth, uint64_t l, uint64_t r) {
  if (depth > 0) {
    int w = __builtin_popcountll(l) + __builtin_popcountll(r);
    if (w < minw) {
      #pragma omp critical(mw)
      { if (w < minw) minw = w; }
    }
    if (w < d && nlight < 500) {
      uint64_t s = side == 0 ? l : r;            /* the G-side identity bits */
      #pragma omp critical
      { if (nlight < 500) { printf("light"); for (int i = 0; i < n; i++) if (s >> i & 1) printf(" %d", i + 1); printf("\n"); nlight++; } }
    }
  }
  if (depth == t) return;
  for (int i = start; i < n; i++) dfs(side, i + 1, depth + 1, l ^ L[side][i], r ^ Rt[side][i]);
}
int main(int argc, char **argv) {
  n = atoi(argv[1]); d = atoi(argv[2]); t = (d - 1) / 2;
  char *b = malloc(n * n + 2);
  int c, k = 0;
  while (k < n * n && (c = getchar()) != EOF) if (c == '0' || c == '1') b[k++] = c;
  if (k != n * n) { fprintf(stderr, "need %d bits, got %d\n", n * n, k); return 2; }
  for (int i = 0; i < n; i++) {
    L[0][i] = 1ULL << i; Rt[0][i] = 0; L[1][i] = 0; Rt[1][i] = 1ULL << i;
    for (int j = 0; j < n; j++) {
      if (b[n*i + j] == '1') Rt[0][i] |= 1ULL << j;   /* G  row i: e_i | A_i      */
      if (b[n*j + i] == '1') L[1][i] |= 1ULL << j;    /* G' row i: (A^T)_i | e_i  */
    }
  }
  #pragma omp parallel for schedule(dynamic)
  for (int job = 0; job < 2 * n; job++) {
    int side = job / n, i = job % n;
    dfs(side, i + 1, 1, L[side][i], Rt[side][i]);
  }
  if (minw < d) printf("min distance %d\n", minw); else printf("d>=%d (exact search below %d)\n", d, d);
  return 0;
}
